"""Explain metadata lookup priority, offsets, runtime independence and page copies."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1749': ('안내소에서 특수 구역 담당자에게 먼저 묻고, 그다음 기종별 담당자에게 물어요. 앞에서 답을 얻었다면 뒤 담당자의 답으로 다시 바꾸지 않아요.', '검사 정보 조회의 우선순위와 origin 주소 정렬을 이해합니다.', 'origin 정렬 → vmalloc/module → arch → 일반 page 순서를 쓰고 앞에서 찾으면 반환 화살표를 그리세요.', ['kmsan_get_metadata는 데이터 주소에 대응하는 검사 정보 주소를 찾는 함수예요. is_origin이 참이면 원인 정보,거짓이면 준비 상태 shadow를 찾아요. 한 함수 안에 주소 종류별로 여러 길이 있어요.', '먼저 origin 요청이면 주소를4바이트 경계로 내려 맞춰요. 예를 들어 주소1007은1004가 돼요. 원인 정보가4바이트 묶음과 관련되기 때문이에요. 뒤의 분류와 조회에는 이렇게 정리한 주소를 사용해요.', '첫째 길은 vmalloc 또는 module 영역이에요. 그 범위이면 vmalloc_meta로 대응 주소를 계산해 바로 반환해요. 뒤의 arch나 일반 page 경로까지 모두 실행해 결과를 비교하는 구조가 아니에요.', '둘째 길은 arch_kmsan_get_meta_or_null이에요. arch는 CPU 아키텍처별 구현을 뜻해요. 기종별로 특별하게 처리해야 하는 검사 정보 주소를 먼저 물어보고,결과 ret가NULL이 아니면 바로 돌려줘요.', '셋째는 일반 page 경로예요. 앞의 특별한 두 경로에서 끝나지 않았을 때 페이지를 찾아 검사 정보 연결과 페이지 안 위치를 이용해 주소를 구해요. 일반 경로가 기종별 결과를 무조건 덮는 것이 아니에요.', '이런 순서는 각 주소 종류에 맞는 처리를 선택하기 위한 것이에요. 함수를 위에서부터 읽으며 return이 나오면 그 호출은 끝난다는 점을 표시해 보세요. 여러 조회 기능이 있어도 모든 입력에 모든 기능을 실행하지는 않아요.'], [('특수 범위가 아닌 주소에서 arch 함수가NULL이 아닌 결과를 주면 일반 page 조회도 하나요?', ['네. 항상 일반 page 결과로 덮어요', '아니요. arch 결과를 먼저 반환해요'], '정답은 두 번째예요. if(ret) return ret가 page 조회보다 앞에 있어요. 앞 단계가 답을 주면 그 호출은 거기서 끝나요.'), ('origin 주소를4바이트 아래 경계로 맞추는 시점은 언제인가요?', ['조회 함수 시작에서 먼저 해요', '반환한 뒤에 언제나 호출자가 복구해요'], '정답은 첫 번째예요. is_origin이면 ALIGN_DOWN을 수행하고 그 주소로 뒤 분기에 들어가요. 정렬과 분류의 순서를 구별하세요.')]), 'os1750': ('건물 안의 위치를 찾으려면 건물 정보와 몇 칸 떨어진 곳인지를 함께 알아야 해요. 검사표에서도 페이지 시작 주소에 그 안의 위치를 더해요.', '유효 주소 확인과 메타데이터 페이지 내부 offset 계산을 이해합니다.', '데이터 페이지 시작4096·주소4103에서 shadow는+7,origin은정렬후+4가 됨을 적으세요.', ['virt_to_page_or_null은 주소를 페이지 정보로 바꾸기 전에 kmsan_virt_addr_valid를 확인해요. 이 검사에서 참이면 virt_to_page를 부르고 거짓이면NULL을 반환해요. NULL은 얻을 페이지 정보가 없다는 값이에요.', '일반 get_metadata 경로는 이 결과 page가 없으면NULL로 끝나요. page가 있더라도 shadow와 origin 두 연결이 모두 있지 않으면 역시NULL이에요. 숫자 주소를 받았다는 사실만으로 검사 정보를 찾았다고 할 수는 없어요.', '필요한 연결이 있으면 offset_in_page(addr)를 계산해요. offset은 페이지 시작에서 몇 바이트 떨어졌는지 나타내요. 페이지 크기4096,시작4096,주소4103이면 offset은7이에요.', 'shadow 요청에서는 바이트 위치를 그대로 써서 shadow 페이지 시작에7을 더해요. origin 요청은 앞에서4바이트 아래로 정렬했으므로4103이4100이 되고 offset은4예요. 그4를origin 페이지 시작에 더해요.', '같은 데이터 주소를 줘도 두 결과의 위치가 다른 이유는 검사 정보의 단위가 다르기 때문이에요. shadow는 바이트별 준비 상태를 따라가고 origin은4바이트 묶음과 연결돼요. origin도무조건+7이라고 계산하면 정렬 단계를 놓친 것이에요.', '이 경로는 조건에 맞는 일반 주소의 조회를 설명해요. 기종별 유효성 함수가 모든 가상 주소 종류를 똑같이 다룬다고 가정하면 안 돼요. 특수 범위와 arch 경로는 앞 수업처럼 먼저 처리되며 실제 메모리 수명 조건도 별도예요.'], [('페이지 안offset7 주소의 origin 조회는 어느 offset을 사용하나요?', ['7이에요', '4예요'], '정답은 두 번째예요. origin 요청은4바이트 경계로 내려 맞추므로7에서4로 가요. shadow는7을 유지하지만 origin은정렬된 위치를 써요.'), ('유효 주소 확인이 거짓이어도 virt_to_page를 무조건 호출하나요?', ['아니요. 이 helper는NULL을 돌려줘요', '네. 모든 포인터를 페이지로 바꿔요'], '정답은 첫 번째예요. if(kmsan_virt_addr_valid(vaddr))일 때만 변환해요. else는NULL이므로 변환 전에 조건이 있어요.')]), 'os1751': ('검사 담당자가 검사표를 찾는 일까지 금지되면 정작 검사를 할 수 없어요. 검사 일을 새로 시작해도 되는지와 검사표가 어디 있는지는 서로 다른 질문이에요.', '메타데이터 조회와 상위 검사 진입 제한을 구별합니다.', 'get_metadata는주소찾기,copy_page_meta는진입조건검사라고 적고 runtime 안에서도 내부조회가 필요한 이유를 써 보세요.', ['runtime은 실행 중 검사 기능을 수행하는 코드예요. 재귀 guard는 검사 코드가 다시 자신에게 들어오는 일을 피하려고 현재 상태를 확인하는 장치예요. 하지만 모든 함수가 같은 위치에서 이 장치를 사용하는 것은 아니에요.', 'kmsan_get_metadata 위 주석은 반환값이 runtime 안인지 밖인지에 의존하지 않아야 한다고 설명해요. 이 함수 본문에는 kmsan_in_runtime이면 무조건NULL로 반환하는 분기가 없어요.', '검사 도구 내부에서도 shadow와 origin의 위치를 찾아야 상태를 읽고 바꿀 수 있어요. 내부라는 이유만으로 모든 조회를NULL로 바꾸면 필요한 검사 정보에 접근할 수 없어요. 주소 조회와 검사 작업의 새 진입을 구별하는 이유예요.', '반면 kmsan_copy_page_meta 같은 상위 작업에는 kmsan_in_runtime 조건으로 돌아가는 코드가 있어요. 어떤 작업을 실행할지 판단하는 계층과 실제 메타데이터 주소를 찾는 계층의 책임이 달라요. 한 함수의 guard를 다른 함수에도 있다고 추측하지 마세요.', '그렇다고 get_metadata가 언제나 유효한 포인터를 준다는 뜻은 아니에요. 미추적 주소나 필요한 페이지 연결이 없는 경우NULL이 나올 수 있어요. 원문은 호출자가 필요한 경우NULL이 아닌지 확인해야 한다고 설명해요.', '같은 주소·같은 매핑 조건에서 runtime 여부만으로 결과를 바꾸지 않는다는 계약과,메모리 매핑이나 대상 수명이 실제로 바뀌는 일은 별개예요. 주소를 한 번 찾았다고 그 저장 공간이 영원히 존재하는 것은 아니에요.'], [('get_metadata는runtime 안이면 반드시NULL을 반환하나요?', ['네. 내부 조회는 전부 금지해요', '아니요. 그런runtime guard 분기는 없어요'], '정답은 두 번째예요. 주석도runtime 여부에 반환이 의존하지 않아야 한다고 해요. 메타데이터 주소 찾기와 상위 작업의 재귀 방지를 구별하세요.'), ('호출자는 필요한 경우 반환 포인터가NULL인지 확인해야 하나요?', ['네. 원문에 명시된 호출 조건이에요', '아니요. 모든 주소에 검사 정보가 있어요'], '정답은 첫 번째예요. runtime 안에서도 조회할 수 있다는 뜻이 모든 주소에 정보가 있다는 뜻은 아니에요. 없는 결과를 사용하지 않도록 확인해야 해요.')]), 'os1752': ('한 페이지의 내용을 옮긴 뒤 그 페이지의 두 검사표도 옮겨야 해요. 이번 도우미는 검사표 두 장을 그대로 복사하며 실제 공책 내용은 별도 작업이에요.', '페이지 단위 메타데이터 복사와 원인 연결 생성의 차이를 이해합니다.', 'data 복사와 shadow·origin 복사를 따로 그리세요. 검사 복사 부분에 진입→shadow한페이지→origin한페이지→종료를 적으세요.', ['kmsan_copy_page_meta는 한 데이터 페이지에 대응하는 검사 정보를 복사하는 함수예요. dst는도착 페이지,src는원본 페이지예요. shadow는준비 상태표이고 origin은원인 정보표예요.', '먼저 KMSAN이 비활성이거나 kmsan_in_runtime이 참이면 돌아가요. 다음으로 도착 페이지가 없거나 메타데이터 연결이 부족하면 역시돌아가요. 실제 복사 전에 필요한 조건을 확인하는 순서예요.', '도착지는 추적되지만 원본이 없거나 원본 메타데이터가 없으면 도착지 한 페이지를 unpoison하고 끝내요. 이는검사 상태를 준비됨으로 표시하는 정책이며 실제 도착 데이터를0으로 채운다는 뜻이 아니에요.', '두 페이지 모두 필요한 정보가 있으면 enter_runtime으로 들어간 뒤 shadow를PAGE_SIZE만큼 __memcpy해요. 이어origin도PAGE_SIZE만큼 __memcpy하고 leave_runtime으로 나와요. 페이지4096인 예라면 검사 정보4096바이트를 각각 두 번 옮겨요.', '복사 주소는 shadow_ptr_for와 origin_ptr_for로 얻어요. 따라서 실제 데이터 페이지를 이 두 __memcpy가 복사하는 것이 아니에요. 원래 데이터 이동과 그에 맞춘 검사 정보 이동을 그림에서 분리하세요.', '앞에서 본 바이트 단위 memmove_metadata는 원인 연결을 새로 시도하는 경로가 있었어요. 이 페이지 함수에는 chain_origin을 바이트마다 부르는 코드가 없고 origin 페이지를 그대로 복사해요. 이름에 복사가 공통으로 들어가도 원인 기록 처리 방식은 구현마다 다를 수 있어요.'], [('이 페이지 복사 도우미의 두 __memcpy 대상은 무엇인가요?', ['실제 사용자 데이터 버퍼 두 개예요', 'shadow페이지와 origin페이지예요'], '정답은 두 번째예요. 인자가 shadow_ptr_for와 origin_ptr_for예요. 검사 정보 복사와 실제 데이터 복사의 대상을 혼동하지 마세요.'), ('이 함수는 원인 연결을바이트마다 새로 만들나요?', ['아니요. origin페이지를 그대로 __memcpy해요', '네. 모든 바이트에서 chain_origin을 호출해요'], '정답은 첫 번째예요. 본문에는 페이지 크기의 두 복사와 진입·종료가 있어요. 바이트 단위 helper의 원인 연결 동작을 여기에 그대로 적용하면 안 돼요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_433.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
